# -*- coding: utf-8 -*-\n# =============================================================================\n# Process Name: Image Tile Extraction and Rendering\n# =============================================================================\n# Description:\n#   Converts various document formats (PDF, web URLs, local images)\n#   into standardized image tiles for PixelRAG indexing.\n#\n# File: renderer.py\n# Project: ai-breadboard\n# Package: src.rag.pixel\n# Author: hypo69\n# Copyright: © 2026 hypo69\n# =============================================================================\n\nfrom __future__ import annotations\n\nimport asyncio\nimport hashlib\nimport logging\nimport time\nfrom abc import ABC, abstractmethod\nfrom dataclasses import dataclass, asdict\nfrom pathlib import Path\nfrom typing import List, Optional, Tuple, Dict, Any\n\nimport numpy as np\nfrom PIL import Image, ImageDraw, ImageFont\n\n\nlogger = logging.getLogger(__name__)\n\n\n@dataclass\nclass RenderedTile:\n    \"\"\"Result of rendering a document source into an image tile.\"\"\"\n    tile_id: str\n    source_type: str  # 'pdf', 'web', 'local_image'\n    source_path: str  # URL or file path\n    page_number: Optional[int] = None  # For PDF pages\n    image: Optional[Image.Image] = None  # PIL Image object\n    image_size: Tuple[int, int] = (0, 0)  # (width, height)\n    timestamp: float = 0.0\n    error: Optional[str] = None  # Error message if rendering failed\n\n    def to_dict(self) -> Dict[str, Any]:\n        \"\"\"Convert to dictionary (excluding PIL Image).\"\"\"\n        d = asdict(self)\n        d.pop('image', None)  # Remove PIL Image object\n        return d\n\n\nclass TileRenderer(ABC):\n    \"\"\"\n    ## hypo69 docblock\n    Abstract base class for converting document sources into image tiles.\n    \n    Subclasses implement specific rendering logic for different formats:\n    - PDFTileRenderer: Converts PDF pages to images\n    - WebScreenshotRenderer: Renders web URLs to screenshots\n    - LocalImageRenderer: Processes local image files\n    \"\"\"\n\n    def __init__(\n        self,\n        tile_size: Tuple[int, int] = (1024, 1024),\n        quality: int = 85,\n        output_format: str = \"PNG\"\n    ) -> None:\n        \"\"\"\n        ## hypo69 docblock\n        Initialize tile renderer with output settings.\n\n        Args:\n            tile_size: Target size for output tiles (width, height)\n            quality: JPEG compression quality (0-100, PNG ignores this)\n            output_format: Image format ('PNG' or 'JPEG')\n        \"\"\"\n        self.tile_size = tile_size\n        self.quality = quality\n        self.output_format = output_format.upper()\n        self.max_tile_size = (2048, 2048)  # Safety limit\n\n    @abstractmethod\n    async def render(self, source: str | Path) -> List[RenderedTile]:\n        \"\"\"\n        ## hypo69 docblock\n        Render document source into list of image tiles.\n\n        Args:\n            source: Document path or URL to render\n\n        Returns:\n            List[RenderedTile]: Rendered tiles with metadata\n        \"\"\"\n        pass\n\n    @staticmethod\n    def _resize_image(\n        image: Image.Image,\n        target_size: Tuple[int, int],\n        maintain_aspect: bool = True\n    ) -> Image.Image:\n        \"\"\"\n        ## hypo69 docblock\n        Resize image to target size, optionally maintaining aspect ratio.\n\n        Args:\n            image: PIL Image to resize\n            target_size: Target (width, height)\n            maintain_aspect: If True, add padding; if False, stretch\n\n        Returns:\n            Image.Image: Resized image\n        \"\"\"\n        if maintain_aspect:\n            # Maintain aspect ratio with padding\n            image.thumbnail(target_size, Image.Resampling.LANCZOS)\n            \n            # Create new image with padding\n            new_image = Image.new(\n                'RGB',\n                target_size,\n                color=(255, 255, 255)  # White background\n            )\n            # Center paste\n            offset = (\n                (target_size[0] - image.width) // 2,\n                (target_size[1] - image.height) // 2\n            )\n            new_image.paste(image, offset)\n            return new_image\n        else:\n            # Stretch to exact size\n            return image.resize(target_size, Image.Resampling.LANCZOS)\n\n    @staticmethod\n    def _compute_image_hash(image: Image.Image) -> str:\n        \"\"\"\n        ## hypo69 docblock\n        Compute SHA-256 hash of image content.\n\n        Args:\n            image: PIL Image to hash\n\n        Returns:\n            str: Hex-encoded SHA-256 hash (truncated to 16 chars)\n        \"\"\"\n        # Convert to bytes and hash\n        image_bytes = image.tobytes()\n        hash_obj = hashlib.sha256(image_bytes)\n        return hash_obj.hexdigest()[:16]\n\n\nclass PDFTileRenderer(TileRenderer):\n    \"\"\"\n    ## hypo69 docblock\n    Extract PDF pages as image tiles.\n    \n    Supports:\n    - Text and scanned PDFs\n    - Custom DPI for rendering quality\n    - Page range selection\n    - Error handling for corrupted PDFs\n    \"\"\"\n\n    def __init__(\n        self,\n        tile_size: Tuple[int, int] = (1024, 1024),\n        dpi: int = 150,\n        quality: int = 85,\n        max_pages: Optional[int] = None\n    ) -> None:\n        \"\"\"\n        ## hypo69 docblock\n        Initialize PDF renderer.\n\n        Args:\n            tile_size: Target tile size\n            dpi: DPI for PDF rendering (higher = better quality, slower)\n            quality: JPEG compression quality\n            max_pages: Max pages to extract (None = all)\n        \"\"\"\n        super().__init__(tile_size, quality, \"PNG\")\n        self.dpi = dpi\n        self.max_pages = max_pages\n        self._pdf2image_available = self._check_pdf2image()\n\n    def _check_pdf2image(self) -> bool:\n        \"\"\"\n        ## hypo69 docblock\n        Check if pdf2image is available.\n\n        Returns:\n            bool: True if pdf2image can be imported\n        \"\"\"\n        try:\n            import pdf2image\n            return True\n        except ImportError:\n            logger.warning(\n                \"pdf2image not available. Install: pip install pdf2image\"\n            )\n            return False\n\n    async def render(self, source: str | Path) -> List[RenderedTile]:\n        \"\"\"\n        ## hypo69 docblock\n        Extract PDF pages as image tiles.\n\n        Args:\n            source: Path to PDF file\n\n        Returns:\n            List[RenderedTile]: Rendered page tiles\n        \"\"\"\n        tiles = []\n        source_path = Path(source)\n\n        if not source_path.exists():\n            logger.error(f\"PDF not found: {source_path}\")\n            return tiles\n\n        if not self._pdf2image_available:\n            logger.error(\"pdf2image not available, cannot render PDF\")\n            return tiles\n\n        try:\n            from pdf2image import convert_from_path\n            import tempfile\n\n            logger.info(f\"Rendering PDF: {source_path}\")\n\n            # Convert PDF pages to images\n            # Use temporary directory for performance\n            with tempfile.TemporaryDirectory() as temp_dir:\n                pages = await asyncio.to_thread(\n                    convert_from_path,\n                    str(source_path),\n                    dpi=self.dpi,\n                    fmt=\"ppm\"\n                )\n\n                # Limit pages if specified\n                pages = pages[:self.max_pages] if self.max_pages else pages\n\n                for page_num, page_image in enumerate(pages, start=1):\n                    try:\n                        # Convert to RGB\n                        if page_image.mode != 'RGB':\n                            page_image = page_image.convert('RGB')\n\n                        # Resize\n                        resized = self._resize_image(\n                            page_image,\n                            self.tile_size,\n                            maintain_aspect=True\n                        )\n\n                        # Create tile metadata\n                        tile = RenderedTile(\n                            tile_id=f\"{source_path.stem}_page_{page_num:04d}\",\n                            source_type=\"pdf\",\n                            source_path=str(source_path),\n                            page_number=page_num,\n                            image=resized,\n                            image_size=resized.size,\n                            timestamp=time.time()\n                        )\n                        tiles.append(tile)\n\n                    except Exception as e:\n                        logger.error(f\"Error processing page {page_num}: {e}\")\n                        continue\n\n                logger.info(f\"Extracted {len(tiles)} tiles from PDF\")\n\n        except Exception as e:\n            logger.error(f\"PDF rendering failed: {e}\")\n            return tiles\n\n        return tiles\n\n\nclass WebScreenshotRenderer(TileRenderer):\n    \"\"\"\n    ## hypo69 docblock\n    Render web URLs to screenshots.\n    \n    Features:\n    - Headless browser rendering (Playwright)\n    - Full-page screenshot support\n    - JavaScript rendering support\n    - Timeout handling\n    \"\"\"\n\n    def __init__(\n        self,\n        tile_size: Tuple[int, int] = (1024, 1024),\n        timeout_sec: int = 30,\n        quality: int = 85,\n        wait_until: str = \"networkidle\"\n    ) -> None:\n        \"\"\"\n        ## hypo69 docblock\n        Initialize web screenshot renderer.\n\n        Args:\n            tile_size: Target tile size for screenshots\n            timeout_sec: Maximum time to wait for page load\n            quality: JPEG compression quality\n            wait_until: Wait condition ('load', 'domcontentloaded', 'networkidle')\n        \"\"\"\n        super().__init__(tile_size, quality, \"PNG\")\n        self.timeout_sec = timeout_sec\n        self.wait_until = wait_until\n        self._playwright_available = self._check_playwright()\n\n    def _check_playwright(self) -> bool:\n        \"\"\"\n        ## hypo69 docblock\n        Check if Playwright is available.\n\n        Returns:\n            bool: True if playwright can be imported\n        \"\"\"\n        try:\n            import playwright\n            return True\n        except ImportError:\n            logger.warning(\n                \"Playwright not available. Install: pip install playwright && \"\n                \"playwright install chromium\"\n            )\n            return False\n\n    async def render(self, source: str | Path) -> List[RenderedTile]:\n        \"\"\"\n        ## hypo69 docblock\n        Render web URL to screenshot tiles.\n\n        Args:\n            source: URL to render\n\n        Returns:\n            List[RenderedTile]: Screenshot tiles (usually 1 per page)\n        \"\"\"\n        tiles = []\n        url = str(source)\n\n        # Validate URL\n        if not url.startswith((\"http://\", \"https://\")):\n            logger.error(f\"Invalid URL: {url}\")\n            return tiles\n\n        if not self._playwright_available:\n            logger.error(\"Playwright not available, cannot render web URL\")\n            return tiles\n\n        try:\n            from playwright.async_api import async_playwright\n\n            logger.info(f\"Rendering web page: {url}\")\n\n            async with async_playwright() as p:\n                browser = await p.chromium.launch(headless=True)\n                context = await browser.new_context(\n                    viewport=dict(width=1920, height=1080)\n                )\n                page = await context.new_page()\n\n                try:\n                    # Navigate to URL\n                    await asyncio.wait_for(\n                        page.goto(\n                            url,\n                            wait_until=self.wait_until,\n                            timeout=self.timeout_sec * 1000\n                        ),\n                        timeout=self.timeout_sec\n                    )\n\n                    # Get page dimensions\n                    dimensions = await page.evaluate(\n                        \"() => ({\"\n                        \"  width: document.documentElement.scrollWidth,\"\n                        \"  height: document.documentElement.scrollHeight\"\n                        \"})\"\n                    )\n\n                    # Capture screenshot\n                    screenshot_bytes = await page.screenshot(\n                        full_page=True,\n                        type=\"png\"\n                    )\n\n                    # Convert to PIL Image\n                    from io import BytesIO\n                    screenshot_image = Image.open(BytesIO(screenshot_bytes))\n\n                    # Resize if needed\n                    resized = self._resize_image(\n                        screenshot_image,\n                        self.tile_size,\n                        maintain_aspect=True\n                    )\n\n                    # Create tile\n                    tile = RenderedTile(\n                        tile_id=f\"web_{hashlib.md5(url.encode()).hexdigest()[:8]}\",\n                        source_type=\"web\",\n                        source_path=url,\n                        image=resized,\n                        image_size=resized.size,\n                        timestamp=time.time()\n                    )\n                    tiles.append(tile)\n\n                    logger.info(\n                        f\"Rendered web page: {dimensions['width']}x\"\n                        f\"{dimensions['height']} px\"\n                    )\n\n                except asyncio.TimeoutError:\n                    logger.error(f\"Page load timeout: {url}\")\n                except Exception as e:\n                    logger.error(f\"Web rendering error: {e}\")\n                finally:\n                    await context.close()\n                    await browser.close()\n\n        except Exception as e:\n            logger.error(f\"Web screenshot rendering failed: {e}\")\n            return tiles\n\n        return tiles\n\n\nclass LocalImageRenderer(TileRenderer):\n    \"\"\"\n    ## hypo69 docblock\n    Process local image files for indexing.\n    \n    Supports:\n    - Multiple image formats (PNG, JPEG, GIF, WebP, etc.)\n    - Automatic format detection\n    - EXIF rotation correction\n    - Batch processing\n    \"\"\"\n\n    def __init__(\n        self,\n        tile_size: Tuple[int, int] = (1024, 1024),\n        quality: int = 85,\n        auto_rotate: bool = True\n    ) -> None:\n        \"\"\"\n        ## hypo69 docblock\n        Initialize local image renderer.\n\n        Args:\n            tile_size: Target tile size\n            quality: JPEG compression quality\n            auto_rotate: Auto-rotate based on EXIF orientation\n        \"\"\"\n        super().__init__(tile_size, quality, \"PNG\")\n        self.auto_rotate = auto_rotate\n        self.supported_formats = {\n            '.png', '.jpg', '.jpeg', '.gif', '.webp', '.bmp', '.tiff'\n        }\n\n    async def render(self, source: str | Path) -> List[RenderedTile]:\n        \"\"\"\n        ## hypo69 docblock\n        Process single local image file.\n\n        Args:\n            source: Path to image file\n\n        Returns:\n            List[RenderedTile]: Processed image tiles (usually 1 per file)\n        \"\"\"\n        tiles = []\n        source_path = Path(source)\n\n        if not source_path.exists():\n            logger.error(f\"Image not found: {source_path}\")\n            return tiles\n\n        if source_path.suffix.lower() not in self.supported_formats:\n            logger.warning(f\"Unsupported image format: {source_path.suffix}\")\n            return tiles\n\n        try:\n            # Open image\n            image = Image.open(source_path)\n\n            # Auto-rotate if needed\n            if self.auto_rotate:\n                from PIL.ImageOps import exif_transpose\n                image = exif_transpose(image)\n\n            # Convert to RGB\n            if image.mode != 'RGB':\n                image = image.convert('RGB')\n\n            # Resize\n            resized = self._resize_image(\n                image,\n                self.tile_size,\n                maintain_aspect=True\n            )\n\n            # Create tile\n            tile = RenderedTile(\n                tile_id=f\"local_{source_path.stem}\",\n                source_type=\"local_image\",\n                source_path=str(source_path),\n                image=resized,\n                image_size=resized.size,\n                timestamp=time.time()\n            )\n            tiles.append(tile)\n\n            logger.info(f\"Processed image: {source_path}\")\n\n        except Exception as e:\n            logger.error(f\"Image processing failed: {e}\")\n            return tiles\n\n        return tiles\n\n    async def render_batch(\n        self,\n        source_dir: Path,\n        recursive: bool = True\n    ) -> List[RenderedTile]:\n        \"\"\"\n        ## hypo69 docblock\n        Process all images in directory.\n\n        Args:\n            source_dir: Directory containing images\n            recursive: Process subdirectories\n\n        Returns:\n            List[RenderedTile]: All processed image tiles\n        \"\"\"\n        all_tiles = []\n        source_dir = Path(source_dir)\n\n        if not source_dir.is_dir():\n            logger.error(f\"Not a directory: {source_dir}\")\n            return all_tiles\n\n        # Find all image files\n        pattern = \"**/*\" if recursive else \"*\"\n        image_files = [\n            f for f in source_dir.glob(pattern)\n            if f.is_file() and f.suffix.lower() in self.supported_formats\n        ]\n\n        logger.info(f\"Found {len(image_files)} images in {source_dir}\")\n\n        # Process all images\n        for image_file in image_files:\n            tiles = await self.render(image_file)\n            all_tiles.extend(tiles)\n\n        return all_tiles\n\n\nclass RendererFactory:\n    \"\"\"\n    ## hypo69 docblock\n    Factory for creating appropriate renderer based on source type.\n    \"\"\"\n\n    @staticmethod\n    def get_renderer(\n        source: str | Path,\n        tile_size: Tuple[int, int] = (1024, 1024)\n    ) -> Optional[TileRenderer]:\n        \"\"\"\n        ## hypo69 docblock\n        Get appropriate renderer for source.\n\n        Args:\n            source: Document path or URL\n            tile_size: Target tile size\n\n        Returns:\n            TileRenderer: Appropriate renderer or None\n        \"\"\"\n        source_str = str(source).lower()\n\n        # Web URL\n        if source_str.startswith((\"http://\", \"https://\")):\n            return WebScreenshotRenderer(tile_size)\n\n        # PDF file\n        if source_str.endswith(\".pdf\"):\n            return PDFTileRenderer(tile_size)\n\n        # Local image\n        if any(source_str.endswith(f) for f in [\n            \".png\", \".jpg\", \".jpeg\", \".gif\", \".webp\", \".bmp\", \".tiff\"\n        ]):\n            return LocalImageRenderer(tile_size)\n\n        logger.warning(f\"Unknown source type: {source}\")\n        return None\n\n    @staticmethod\n    async def render(\n        source: str | Path,\n        tile_size: Tuple[int, int] = (1024, 1024)\n    ) -> List[RenderedTile]:\n        \"\"\"\n        ## hypo69 docblock\n        Render document source using appropriate renderer.\n\n        Args:\n            source: Document path or URL\n            tile_size: Target tile size\n\n        Returns:\n            List[RenderedTile]: Rendered tiles\n        \"\"\"\n        renderer = RendererFactory.get_renderer(source, tile_size)\n        if renderer is None:\n            logger.error(f\"No renderer found for: {source}\")\n            return []\n\n        return await renderer.render(source)\n"